--
-- Name: _bcast_bump(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bcast_bump(bid uuid, col text, delta integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  EXECUTE format(
    'UPDATE broadcasts SET %I = GREATEST(0, %I + $1), updated_at = NOW() WHERE id = $2',
    col, col
  ) USING delta, bid;
END;
$_$;


--
-- Name: _bcast_cols_for_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._bcast_cols_for_status(s text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  -- 'pending' contributes to nothing.
  IF s = 'pending' THEN RETURN ARRAY[]::TEXT[]; END IF;
  IF s = 'sent'      THEN RETURN ARRAY['sent_count']; END IF;
  IF s = 'delivered' THEN RETURN ARRAY['sent_count','delivered_count']; END IF;
  IF s = 'read'      THEN RETURN ARRAY['sent_count','delivered_count','read_count']; END IF;
  IF s = 'replied'   THEN RETURN ARRAY['sent_count','delivered_count','read_count','replied_count']; END IF;
  IF s = 'failed'    THEN RETURN ARRAY['failed_count']; END IF;
  RETURN ARRAY[]::TEXT[];
END;
$$;


--
-- Name: active_ws(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.active_ws() RETURNS uuid
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  raw TEXT;
BEGIN
  raw := NULLIF(current_setting('app.workspace_id', true), '');
  IF raw IS NULL OR raw = '' THEN
    RETURN NULL;
  END IF;
  RETURN raw::uuid;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;


--
-- Name: apply_billing_payment(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_billing_payment(pay uuid, months integer DEFAULT 6) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  p public.billing_payments;
BEGIN
  SELECT * INTO p FROM public.billing_payments WHERE id = pay FOR UPDATE;
  IF NOT FOUND OR p.status NOT IN ('pending', 'expired') THEN
    RETURN FALSE;
  END IF;
  UPDATE public.billing_payments SET status = 'paid', paid_at = NOW(), error = NULL WHERE id = pay;
  PERFORM public.grant_credits(p.workspace_id, p.credits, 'purchase', NOW() + make_interval(months => GREATEST(months, 1)), pay, NULL, p.created_by);
  RETURN TRUE;
END;
$$;


--
-- Name: billing_on_workspace_created(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_on_workspace_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  cfg JSONB;
  credits INTEGER;
  months INTEGER;
BEGIN
  INSERT INTO public.billing_accounts (workspace_id) VALUES (NEW.id) ON CONFLICT DO NOTHING;
  SELECT value INTO cfg FROM public.platform_settings WHERE key = 'billing';
  credits := COALESCE((cfg->>'welcome_credits')::INTEGER, 100);
  months := COALESCE((cfg->>'expiry_months')::INTEGER, 6);
  IF credits > 0 THEN
    PERFORM public.grant_credits(NEW.id, credits, 'welcome', NOW() + make_interval(months => GREATEST(months, 1)), NULL, NULL, NULL);
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never block a signup because of billing.
  RAISE WARNING 'billing_on_workspace_created: %', SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: bookings_mark_google_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_mark_google_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  relevant BOOLEAN;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.google_synced_at IS DISTINCT FROM OLD.google_synced_at THEN
      RETURN NEW;
    END IF;
    relevant := NEW.booking_date IS DISTINCT FROM OLD.booking_date
      OR NEW.booking_time IS DISTINCT FROM OLD.booking_time
      OR NEW.duration_minutes IS DISTINCT FROM OLD.duration_minutes
      OR NEW.staff_id IS DISTINCT FROM OLD.staff_id
      OR NEW.status IS DISTINCT FROM OLD.status
      OR NEW.customer_name IS DISTINCT FROM OLD.customer_name
      OR NEW.notes IS DISTINCT FROM OLD.notes
      OR NEW.product_id IS DISTINCT FROM OLD.product_id
      OR NEW.service_id IS DISTINCT FROM OLD.service_id;
    IF NOT relevant THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.google_event_id IS NOT NULL
     OR (NEW.staff_id IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.calendar_connections c
       WHERE c.staff_id = NEW.staff_id AND c.status <> 'revoked'
     )) THEN
    NEW.google_sync_state := 'pending';
    NEW.google_sync_attempts := 0;
    NEW.google_sync_error := NULL;
    NEW.google_sync_version := COALESCE(NEW.google_sync_version, 0) + 1;
  END IF;
  RETURN NEW;
END;
$$;


