$$;


--
-- Name: deals_close_bookkeeping(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_close_bookkeeping() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF NEW.status = 'won' THEN
    NEW.won_at := COALESCE(CASE WHEN TG_OP = 'INSERT' THEN NEW.won_at END, NOW());
    NEW.lost_at := NULL;
    NEW.lost_reason := NULL;
  ELSIF NEW.status = 'lost' THEN
    NEW.lost_at := COALESCE(CASE WHEN TG_OP = 'INSERT' THEN NEW.lost_at END, NOW());
    NEW.won_at := NULL;
  ELSE
    NEW.won_at := NULL;
    NEW.lost_at := NULL;
    NEW.lost_reason := NULL;
    NEW.close_note := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: default_ws_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.default_ws_for_user(uid uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT m.workspace_id FROM public.workspace_members m
  WHERE m.user_id = uid AND m.status = 'active'
  ORDER BY public.ws_role_rank(m.role) DESC, m.created_at ASC
  LIMIT 1
$$;


--
-- Name: enqueue_property_match(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_property_match() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  why TEXT;
BEGIN
  IF NOT NEW.is_active THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workspaces w WHERE w.id = NEW.workspace_id AND w.industry = 'real_estate') THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'INSERT' THEN
    why := 'created';
  ELSIF NOT OLD.is_active THEN
    why := 'activated';
  ELSIF NEW.price IS DISTINCT FROM OLD.price OR NEW.currency IS DISTINCT FROM OLD.currency THEN
    why := 'price';
  ELSIF public.listing_status_of(NEW) IS DISTINCT FROM public.listing_status_of(OLD) THEN
    why := 'status';
  ELSE
    RETURN NULL;
  END IF;
  -- Small delay so a listing being edited in several saves alerts once.
  INSERT INTO public.property_match_jobs (workspace_id, product_id, reason, run_after)
  VALUES (NEW.workspace_id, NEW.id, why, NOW() + INTERVAL '2 minutes')
  ON CONFLICT (product_id) WHERE status = 'pending'
  DO UPDATE SET run_after = EXCLUDED.run_after;
  RETURN NULL;
END;
$$;


--
-- Name: ensure_real_estate_pipeline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_real_estate_pipeline(ws uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pid UUID;
  loc TEXT;
  s JSONB;
  reasons JSONB;
  stage_keys TEXT[] := ARRAY['new', 'qualified', 'viewing_scheduled', 'viewed', 'negotiation', 'reservation', 'won'];
  colors TEXT[] := ARRAY['#3b82f6', '#06b6d4', '#8b5cf6', '#a855f7', '#f97316', '#eab308', '#22c55e'];
  names TEXT[];
  i INT;
BEGIN
  SELECT w.locale, COALESCE(w.settings, '{}'::jsonb) INTO loc, s FROM public.workspaces w WHERE w.id = ws;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Serialize concurrent calls for the same workspace (button double-click).
  PERFORM pg_advisory_xact_lock(hashtext('re_pipeline:' || ws::text));

  SELECT id INTO pid FROM public.pipelines WHERE workspace_id = ws AND key = 'real_estate';
  IF pid IS NULL THEN
    IF loc = 'en' THEN
      names := ARRAY['New lead', 'Qualified', 'Viewing scheduled', 'Viewed', 'Negotiation / Offer', 'Reservation', 'Closed won'];
    ELSE
      names := ARRAY['Nuevo lead', 'Calificado', 'Visita agendada', 'Visitó', 'Negociación / Oferta', 'Separación', 'Cierre ganado'];
    END IF;
    INSERT INTO public.pipelines (workspace_id, name, key, user_id)
    VALUES (ws, CASE WHEN loc = 'en' THEN 'Real estate sales' ELSE 'Ventas inmobiliarias' END, 'real_estate', NULL)
    RETURNING id INTO pid;
    FOR i IN 1 .. array_length(stage_keys, 1) LOOP
      INSERT INTO public.pipeline_stages (pipeline_id, workspace_id, name, position, color, key)
      VALUES (pid, ws, names[i], i - 1, colors[i], stage_keys[i]);
    END LOOP;
  END IF;

  -- Lost reasons: only when the workspace has none configured yet.
  IF jsonb_typeof(s #> '{crm,lost_reasons}') IS DISTINCT FROM 'array'
     OR jsonb_array_length(s #> '{crm,lost_reasons}') = 0 THEN
    IF loc = 'en' THEN
      reasons := '["Insufficient budget", "Did not qualify for a mortgage", "Chose another property", "Bought/rented through another agency", "Stopped responding", "Did not like the area", "Other"]'::jsonb;
    ELSE
      reasons := '["Presupuesto insuficiente", "No calificó para crédito", "Eligió otra propiedad", "Compró/alquiló con otra inmobiliaria", "Dejó de responder", "Zona no le convence", "Otro"]'::jsonb;
    END IF;
    UPDATE public.workspaces
    SET settings = jsonb_set(
      COALESCE(settings, '{}'::jsonb),
      '{crm}',
      CASE WHEN jsonb_typeof(settings -> 'crm') = 'object' THEN settings -> 'crm' ELSE '{}'::jsonb END
        || jsonb_build_object('lost_reasons', reasons)
    )
    WHERE id = ws;
  END IF;

  RETURN pid;
END;
$$;


--
-- Name: expire_credit_lots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_credit_lots() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r RECORD;
  n INTEGER := 0;
BEGIN
  FOR r IN
    SELECT id, workspace_id, credits_remaining FROM public.credit_lots
    WHERE credits_remaining > 0 AND expires_at <= NOW()
    FOR UPDATE SKIP LOCKED
  LOOP
    UPDATE public.credit_lots SET credits_remaining = 0 WHERE id = r.id;
    INSERT INTO public.credit_ledger (workspace_id, kind, credits, lot_id)
    VALUES (r.workspace_id, 'expiry', -r.credits_remaining, r.id);
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$$;


--
-- Name: grant_credits(uuid, integer, text, timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_credits(ws uuid, amount integer, src text, expires timestamp with time zone, pay uuid DEFAULT NULL::uuid, why text DEFAULT NULL::text, actor uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  lot UUID;
BEGIN
  IF amount IS NULL OR amount <= 0 THEN
    RAISE EXCEPTION 'amount must be positive';
  END IF;
  INSERT INTO public.credit_lots (workspace_id, source, credits_total, credits_remaining, expires_at, payment_id, note, created_by)
  VALUES (ws, src, amount, amount, expires, pay, why, actor)
  RETURNING id INTO lot;
  INSERT INTO public.credit_ledger (workspace_id, kind, credits, lot_id, payment_id, note, created_by)
  VALUES (ws, src, amount, lot, pay, why, actor);
  -- New credits re-arm the low/depleted notifications.
  UPDATE public.billing_accounts SET low_notified_at = NULL, depleted_notified_at = NULL WHERE workspace_id = ws;
  RETURN lot;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  meta JSONB := COALESCE(NEW.meta, '{}'::jsonb);
  ws UUID;
  wname TEXT;
BEGIN
  INSERT INTO public.profiles (user_id, full_name, email, business_name, business_type, locale)
  VALUES (
    NEW.id,
    COALESCE(meta ->> 'full_name', ''),
    NEW.email,
    COALESCE(meta ->> 'business_name', ''),
    COALESCE(meta ->> 'business_type', ''),
    CASE WHEN meta ->> 'locale' IN ('es', 'en') THEN meta ->> 'locale' ELSE 'es' END
  );

  IF COALESCE((meta ->> 'invite')::boolean, false) THEN
    RETURN NEW;
  END IF;

  wname := COALESCE(NULLIF(meta ->> 'business_name', ''), NULLIF(meta ->> 'full_name', ''), split_part(NEW.email, '@', 1));
  INSERT INTO public.workspaces (name, slug, industry, country, currency, timezone, locale, created_by)
  VALUES (
    wname,
    public.make_ws_slug(wname),
    public.industry_from_business_type(meta ->> 'business_type'),
    NULLIF(meta ->> 'country', ''),
    COALESCE(NULLIF(meta ->> 'currency', ''), 'USD'),
    COALESCE(NULLIF(meta ->> 'timezone', ''), 'UTC'),
    CASE WHEN meta ->> 'locale' IN ('es', 'en') THEN meta ->> 'locale' ELSE 'es' END,
    NEW.id
  )
  RETURNING id INTO ws;
  INSERT INTO public.workspace_members (workspace_id, user_id, role) VALUES (ws, NEW.id, 'owner');
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


