--
-- Name: industry_from_business_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.industry_from_business_type(bt text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN bt IS NULL OR bt = '' THEN 'generic'
    WHEN lower(bt) LIKE 'healthcare%' THEN 'clinic'
    WHEN lower(bt) = 'education' THEN 'academy'
    WHEN lower(bt) LIKE 'hotel%' OR lower(bt) LIKE '%restaurant%' THEN 'restaurant'
    WHEN lower(bt) IN ('clinic','barbershop','spa_salon','academy','restaurant','store','real_estate','generic') THEN lower(bt)
    ELSE 'generic'
  END
$$;


--
-- Name: is_ws_member(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_ws_member(ws uuid, min_role text DEFAULT 'agent'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.workspace_members m
    WHERE m.workspace_id = ws
      AND m.user_id = public.app_user_id()
      AND m.status = 'active'
      AND public.ws_role_rank(m.role) >= public.ws_role_rank(min_role)
  )
$$;


--
-- Name: jsonb_values_text(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jsonb_values_text(j jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT COALESCE(string_agg(
    CASE jsonb_typeof(v)
      WHEN 'array' THEN (SELECT string_agg(e #>> '{}', ' ') FROM jsonb_array_elements(v) e)
      ELSE v #>> '{}'
    END, ' '), '')
  FROM jsonb_each(COALESCE(j, '{}'::jsonb)) AS x(k, v)
$$;


--
-- Name: lead_profiles_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_profiles_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.workspace_id := OLD.workspace_id;
    NEW.contact_id := OLD.contact_id;
    NEW.created_at := OLD.created_at;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'contact_other_workspace' USING ERRCODE = '23514';
  END IF;
  IF NEW.conversation_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.conversations c WHERE c.id = NEW.conversation_id AND c.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'conversation_other_workspace' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


