--
-- Name: products; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid DEFAULT public.active_ws() NOT NULL,
    category_id uuid,
    name text NOT NULL,
    description text,
    price numeric(14,2),
    compare_at_price numeric(14,2),
    sku text,
    stock integer,
    track_stock boolean DEFAULT false NOT NULL,
    images text[] DEFAULT '{}'::text[] NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    is_featured boolean DEFAULT false NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    search tsvector,
    created_by uuid DEFAULT public.app_user_id(),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    external_source text,
    external_id text,
    external_url text,
    external_synced_at timestamp with time zone,
    external_missing_since timestamp with time zone,
    currency text,
    CONSTRAINT products_currency_check CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT products_external_id_check CHECK (((external_id IS NULL) OR (char_length(external_id) <= 200))),
    CONSTRAINT products_external_source_check CHECK (((external_source IS NULL) OR (char_length(external_source) <= 120))),
    CONSTRAINT products_external_url_check CHECK (((external_url IS NULL) OR (char_length(external_url) <= 2000)))
);


