--
-- Name: make_ws_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.make_ws_slug(n text) RETURNS text
    LANGUAGE sql
    AS $$
  SELECT COALESCE(NULLIF(trim(both '-' from regexp_replace(lower(COALESCE(n, '')), '[^a-z0-9]+', '-', 'g')), ''), 'workspace')
         || '-' || substr(md5(random()::text), 1, 6)
$$;


--
-- Name: meta_message_usage(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meta_message_usage(ws uuid, since timestamp with time zone, until timestamp with time zone) RETURNS TABLE(channel_id uuid, service bigint, marketing bigint, utility bigint, authentication bigint, other_template bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH sent AS (
    SELECT c.channel_id, m.content_type, m.template_name
    FROM public.messages m
    JOIN public.conversations c ON c.id = m.conversation_id
    JOIN public.channels ch ON ch.id = c.channel_id AND ch.type = 'whatsapp'
    WHERE m.workspace_id = ws
      AND m.created_at >= since AND m.created_at < until
      AND m.sender_type IN ('agent', 'bot')
      AND m.content_type <> 'system'
      AND COALESCE(m.is_internal, false) = false
      AND m.status IN ('sent', 'delivered', 'read')
      AND COALESCE(m.metadata->>'source', '') <> 'whatsapp_business_app'
  ),
  classified AS (
    SELECT s.channel_id,
      CASE WHEN s.content_type <> 'template' THEN 'service'
           ELSE COALESCE((
             SELECT lower(t.category) FROM public.message_templates t
             WHERE t.workspace_id = ws AND t.name = s.template_name
               AND (t.channel_id = s.channel_id OR t.channel_id IS NULL)
             ORDER BY (t.channel_id = s.channel_id) DESC NULLS LAST
             LIMIT 1), 'other')
      END AS kind
    FROM sent s
  )
  SELECT channel_id,
    COUNT(*) FILTER (WHERE kind = 'service'),
    COUNT(*) FILTER (WHERE kind = 'marketing'),
    COUNT(*) FILTER (WHERE kind = 'utility'),
    COUNT(*) FILTER (WHERE kind = 'authentication'),
    COUNT(*) FILTER (WHERE kind NOT IN ('service', 'marketing', 'utility', 'authentication'))
  FROM classified
  GROUP BY channel_id;
$$;


--
-- Name: next_workspace_counter(uuid, text); Type: FUNCTION; Schema: public; Owner: -
