--
-- Name: reports_has_column(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_has_column(p_table text, p_column text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
