    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = p_table AND column_name = p_column
  )
$$;


--
-- Name: reports_snapshot(uuid, uuid[], uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_snapshot(p_ws uuid, p_channels uuid[] DEFAULT NULL::uuid[], p_agents uuid[] DEFAULT NULL::uuid[], p_team uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  result JSONB;
  v_internal TEXT := CASE WHEN public.reports_has_column('messages', 'is_internal')
                          THEN ' AND NOT COALESCE(m.is_internal, false)' ELSE '' END;
  v_resolved TEXT := CASE WHEN public.reports_has_column('conversations', 'resolved_at')
                          THEN ' AND (c.resolved_at IS NULL OR c.resolved_at < l.created_at)' ELSE '' END;
  v_team TEXT := CASE
    WHEN to_regclass('public.team_members') IS NULL THEN ''
    WHEN public.reports_has_column('conversations', 'team_id') THEN
      ' AND ($4::uuid IS NULL OR c.team_id = $4 OR c.assigned_agent_id IN (SELECT tm.user_id FROM public.team_members tm WHERE tm.team_id = $4))'
    ELSE
      ' AND ($4::uuid IS NULL OR c.assigned_agent_id IN (SELECT tm.user_id FROM public.team_members tm WHERE tm.team_id = $4))'
  END;
BEGIN
  PERFORM public.reports_guard(p_ws);
  EXECUTE format($q$
    WITH conv AS (
      SELECT c.id, c.channel_id, c.contact_id, c.assigned_agent_id, c.status
      FROM public.conversations c
      WHERE c.workspace_id = $1 AND c.status <> 'closed'
        AND ($2::uuid[] IS NULL OR c.channel_id = ANY($2))
        AND ($3::uuid[] IS NULL OR c.assigned_agent_id = ANY($3))
        %3$s
    ),
    waiting AS (
      SELECT c.id, c.channel_id, c.contact_id, c.assigned_agent_id, l.created_at AS last_at,
             (SELECT min(m.created_at) FROM public.messages m
               WHERE m.conversation_id = c.id AND m.sender_type = 'customer'
                 AND m.content_type <> 'system'
                 AND m.created_at > COALESCE((SELECT max(r.created_at) FROM public.messages r
                                              WHERE r.conversation_id = c.id AND r.sender_type <> 'customer'
                                                AND r.content_type <> 'system' %1$s), '-infinity')) AS since
      FROM public.conversations c
      JOIN conv ON conv.id = c.id
      CROSS JOIN LATERAL (
        SELECT m.sender_type, m.created_at FROM public.messages m
        WHERE m.conversation_id = c.id AND m.content_type <> 'system' %1$s
        ORDER BY m.created_at DESC LIMIT 1
      ) l
      WHERE l.sender_type = 'customer' %2$s
    )
    SELECT jsonb_build_object(
      'unanswered', (SELECT count(*) FROM waiting),
      'oldest_waiting', (SELECT min(since) FROM waiting),
      'waiting', COALESCE((
        SELECT jsonb_agg(x ORDER BY x.since) FROM (
          SELECT w.id AS conversation_id, w.since, w.channel_id, w.assigned_agent_id,
                 COALESCE(ct.name, ct.phone) AS contact
          FROM waiting w LEFT JOIN public.contacts ct ON ct.id = w.contact_id
          ORDER BY w.since LIMIT 20) x), '[]'::jsonb),
      'open_load', COALESCE((
        SELECT jsonb_agg(x) FROM (
          SELECT assigned_agent_id AS user_id,
                 count(*) FILTER (WHERE status = 'open') AS open,
                 count(*) FILTER (WHERE status = 'pending') AS pending
          FROM conv WHERE assigned_agent_id IS NOT NULL GROUP BY 1) x), '[]'::jsonb)
    )
  $q$, v_internal, v_resolved, v_team) INTO result USING p_ws, p_channels, p_agents, p_team;
  RETURN result;
END;
$_$;


--
-- Name: reports_stream(uuid, timestamp with time zone, timestamp with time zone, uuid[], uuid[], uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_stream(p_ws uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_channels uuid[] DEFAULT NULL::uuid[], p_agents uuid[] DEFAULT NULL::uuid[], p_team uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100000) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  result JSONB;
BEGIN
  PERFORM public.reports_guard(p_ws);
  EXECUTE 'WITH ' || public.reports_base_cte() || $q$,
    lim AS (SELECT * FROM msg ORDER BY created_at LIMIT $8 + 1)
    SELECT jsonb_build_object(
      'truncated', (SELECT count(*) FROM lim) > $8,
      'rows', COALESCE((
        SELECT jsonb_agg(jsonb_build_array(
                 conversation_id,
                 CASE sender_type WHEN 'customer' THEN 'c' WHEN 'agent' THEN 'a' ELSE 'b' END,
                 sender_id, ai_agent_id,
                 floor(extract(epoch FROM created_at) * 1000)::bigint) ORDER BY created_at)
        FROM (SELECT * FROM lim ORDER BY created_at LIMIT $8) l), '[]'::jsonb)
    )
  $q$ INTO result USING p_ws, p_from, p_to, 'UTC'::text, p_channels, p_agents, p_team, GREATEST(1, LEAST(p_limit, 200000));
  RETURN result;
END;
$_$;


--
-- Name: reports_volume(uuid, timestamp with time zone, timestamp with time zone, text, uuid[], uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reports_volume(p_ws uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_tz text, p_channels uuid[] DEFAULT NULL::uuid[], p_agents uuid[] DEFAULT NULL::uuid[], p_team uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
  result JSONB;
BEGIN
  PERFORM public.reports_guard(p_ws);
  EXECUTE 'WITH ' || public.reports_base_cte() || $q$
    SELECT jsonb_build_object(
      'by_day', COALESCE((
        SELECT jsonb_agg(x ORDER BY x.day) FROM (
          SELECT to_char(created_at AT TIME ZONE $4, 'YYYY-MM-DD') AS day,
                 count(*) FILTER (WHERE sender_type = 'customer') AS inbound,
                 count(*) FILTER (WHERE sender_type = 'agent') AS agent,
                 count(*) FILTER (WHERE sender_type = 'bot') AS bot
          FROM msg GROUP BY 1) x), '[]'::jsonb),
      'by_channel', COALESCE((
        SELECT jsonb_agg(x) FROM (
          SELECT channel_id,
                 count(*) FILTER (WHERE sender_type = 'customer') AS inbound,
                 count(*) FILTER (WHERE sender_type = 'agent') AS agent,
                 count(*) FILTER (WHERE sender_type = 'bot') AS bot,
                 count(DISTINCT conversation_id) AS conversations
          FROM msg GROUP BY 1) x), '[]'::jsonb),
      'heatmap', COALESCE((
        SELECT jsonb_agg(x) FROM (
          SELECT (extract(isodow FROM created_at AT TIME ZONE $4)::int - 1) AS dow,
                 extract(hour FROM created_at AT TIME ZONE $4)::int AS hour,
                 count(*) AS inbound
          FROM msg WHERE sender_type = 'customer' GROUP BY 1, 2) x), '[]'::jsonb),
      'by_agent', COALESCE((
        SELECT jsonb_agg(x) FROM (
          SELECT sender_id AS user_id, count(*) AS messages, count(DISTINCT conversation_id) AS conversations
          FROM msg WHERE sender_type = 'agent' AND sender_id IS NOT NULL GROUP BY 1) x), '[]'::jsonb),
      'by_ai_agent', COALESCE((
        SELECT jsonb_agg(x) FROM (
          SELECT ai_agent_id, count(*) AS messages, count(DISTINCT conversation_id) AS conversations
          FROM msg WHERE sender_type = 'bot' GROUP BY 1) x), '[]'::jsonb),
      'mix', (
        SELECT jsonb_build_object(
          'ai_only', count(*) FILTER (WHERE b > 0 AND a = 0),
          'human_only', count(*) FILTER (WHERE a > 0 AND b = 0),
          'both', count(*) FILTER (WHERE a > 0 AND b > 0),
          'no_reply', count(*) FILTER (WHERE a = 0 AND b = 0 AND c > 0))
        FROM (SELECT conversation_id,
                     count(*) FILTER (WHERE sender_type = 'agent') AS a,
                     count(*) FILTER (WHERE sender_type = 'bot') AS b,
                     count(*) FILTER (WHERE sender_type = 'customer') AS c
              FROM msg GROUP BY 1) s),
      'conversations_started', (
        SELECT count(*) FROM public.conversations c JOIN conv ON conv.id = c.id
        WHERE c.created_at >= $2 AND c.created_at < $3)
    )
  $q$ INTO result USING p_ws, p_from, p_to, p_tz, p_channels, p_agents, p_team;
  RETURN result;
END;
$_$;


--
-- Name: reverse_billing_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_billing_payment(pay uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  p public.billing_payments;
  l public.credit_lots;
  removed INTEGER := 0;
BEGIN
  SELECT * INTO p FROM public.billing_payments WHERE id = pay FOR UPDATE;
  IF NOT FOUND OR p.status <> 'paid' THEN
    RETURN 0;
  END IF;
  UPDATE public.billing_payments SET status = 'reversed' WHERE id = pay;
  SELECT * INTO l FROM public.credit_lots WHERE payment_id = pay FOR UPDATE;
  IF FOUND AND l.credits_remaining > 0 THEN
    removed := l.credits_remaining;
    UPDATE public.credit_lots SET credits_remaining = 0 WHERE id = l.id;
    INSERT INTO public.credit_ledger (workspace_id, kind, credits, lot_id, payment_id)
    VALUES (p.workspace_id, 'reversal', -removed, l.id, pay);
  END IF;
  RETURN removed;
END;
$$;


--
-- Name: search_products(uuid, text, uuid, jsonb, numeric, numeric, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_products(ws uuid, q text DEFAULT NULL::text, category uuid DEFAULT NULL::uuid, filters jsonb DEFAULT '{}'::jsonb, min_price numeric DEFAULT NULL::numeric, max_price numeric DEFAULT NULL::numeric, in_stock_only boolean DEFAULT false, max_results integer DEFAULT 10, price_currency text DEFAULT NULL::text) RETURNS SETOF public.products
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  tsq tsquery;
  words TEXT;
  k TEXT;
  v JSONB;
  base TEXT;
  sql TEXT;
BEGIN
  words := trim(regexp_replace(public.immutable_unaccent(lower(COALESCE(q, ''))), '[^a-z0-9ñ ]+', ' ', 'g'));
  IF words <> '' THEN
    tsq := to_tsquery('simple', array_to_string(ARRAY(
      SELECT w || ':*' FROM unnest(string_to_array(words, ' ')) w WHERE length(w) > 1
    ), ' | '));
  END IF;

  sql := 'SELECT p.* FROM public.products p WHERE p.workspace_id = $1 AND p.is_active';
  IF category IS NOT NULL THEN sql := sql || ' AND p.category_id = $2'; END IF;
  -- With a currency, price bounds only apply to products priced in it
  -- (p.currency NULL = the workspace currency).
  IF price_currency IS NOT NULL AND (min_price IS NOT NULL OR max_price IS NOT NULL) THEN
    sql := sql || ' AND COALESCE(p.currency, (SELECT w.currency FROM public.workspaces w WHERE w.id = $1)) = $8';
  END IF;
  IF min_price IS NOT NULL THEN sql := sql || ' AND p.price >= $3'; END IF;
  IF max_price IS NOT NULL THEN sql := sql || ' AND p.price <= $4'; END IF;
  IF in_stock_only THEN sql := sql || ' AND (NOT p.track_stock OR COALESCE(p.stock, 0) > 0)'; END IF;
  IF tsq IS NOT NULL THEN
    sql := sql || ' AND (p.search @@ $5 OR public.immutable_unaccent(lower(p.name)) LIKE ''%'' || $6 || ''%'')';
  END IF;

  FOR k, v IN SELECT * FROM jsonb_each(COALESCE(filters, '{}'::jsonb)) LOOP
    IF k !~ '^[a-z0-9_]+$' THEN CONTINUE; END IF;
    IF k LIKE '%\_\_min' THEN
      base := left(k, length(k) - 5);
      sql := sql || format(' AND (p.attributes->>%L) ~ ''^-?[0-9.]+$'' AND (p.attributes->>%L)::numeric >= %s', base, base, (v #>> '{}')::numeric);
    ELSIF k LIKE '%\_\_max' THEN
      base := left(k, length(k) - 5);
      sql := sql || format(' AND (p.attributes->>%L) ~ ''^-?[0-9.]+$'' AND (p.attributes->>%L)::numeric <= %s', base, base, (v #>> '{}')::numeric);
    ELSIF jsonb_typeof(v) = 'array' THEN
      -- any of the values (attribute may itself be an array)
      sql := sql || format(' AND (p.attributes->%L ?| %L OR (p.attributes->>%L) = ANY (%L))',
        k, ARRAY(SELECT jsonb_array_elements_text(v)), k, ARRAY(SELECT jsonb_array_elements_text(v)));
    ELSE
      sql := sql || format(' AND (lower(p.attributes->>%L) = lower(%L) OR p.attributes->%L ? %L)', k, v #>> '{}', k, v #>> '{}');
    END IF;
  END LOOP;

  sql := sql || ' ORDER BY ' ||
    CASE WHEN tsq IS NOT NULL THEN 'ts_rank(p.search, $5) DESC, ' ELSE '' END ||
    'p.is_featured DESC, p.sort_order, p.name LIMIT $7';

  RETURN QUERY EXECUTE sql USING ws, category, min_price, max_price, tsq, words, LEAST(GREATEST(max_results, 1), 50), upper(price_currency);
END;
$_$;


--
-- Name: set_my_availability(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_availability(ws uuid, is_available boolean) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE public.workspace_members
  SET available = is_available, updated_at = NOW()
  WHERE workspace_id = ws AND user_id = public.app_user_id() AND status = 'active'
  RETURNING available
$$;


--
-- Name: set_ws_from_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ws_from_parent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  parent_id UUID;
BEGIN
  IF NEW.workspace_id IS NULL THEN
    parent_id := (to_jsonb(NEW) ->> TG_ARGV[1])::uuid;
    IF parent_id IS NOT NULL THEN
      EXECUTE format('SELECT workspace_id FROM public.%I WHERE id = $1', TG_ARGV[0])
        INTO NEW.workspace_id USING parent_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: set_ws_from_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ws_from_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.workspace_id IS NULL THEN
    NEW.workspace_id := COALESCE(public.active_ws(), public.default_ws_for_user(NEW.user_id));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: spend_credits(uuid, integer, text, uuid, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spend_credits(ws uuid, amount integer, act text, conv uuid DEFAULT NULL::uuid, partial boolean DEFAULT true, why text DEFAULT NULL::text, actor uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  available INTEGER;
  todo INTEGER;
  spent INTEGER := 0;
  take INTEGER;
  r RECORD;
BEGIN
  IF amount IS NULL OR amount <= 0 THEN
    RETURN public.credit_balance(ws);
  END IF;
  -- Lock the live lots so concurrent replies can't spend the same credits.
  SELECT COALESCE(SUM(credits_remaining), 0) INTO available FROM (
    SELECT credits_remaining FROM public.credit_lots
    WHERE workspace_id = ws AND credits_remaining > 0 AND expires_at > NOW()
    FOR UPDATE
  ) l;
  IF available < amount AND NOT partial THEN
    RETURN -1;
  END IF;
  todo := LEAST(amount, available);
  FOR r IN
    SELECT id, credits_remaining FROM public.credit_lots
    WHERE workspace_id = ws AND credits_remaining > 0 AND expires_at > NOW()
    ORDER BY expires_at, created_at
  LOOP
    EXIT WHEN todo <= 0;
    take := LEAST(todo, r.credits_remaining);
    UPDATE public.credit_lots SET credits_remaining = credits_remaining - take WHERE id = r.id;
    todo := todo - take;
    spent := spent + take;
  END LOOP;
  IF spent > 0 THEN
    INSERT INTO public.credit_ledger (workspace_id, kind, credits, action, conversation_id, note, created_by)
    VALUES (ws, CASE WHEN act = 'adjustment' THEN 'adjustment' ELSE 'usage' END, -spent, NULLIF(act, 'adjustment'), conv, why, actor);
  END IF;
  RETURN available - spent;
END;
$$;


--
-- Name: tasks_bookkeeping(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tasks_bookkeeping() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  uid UUID := public.app_user_id();
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF uid IS NOT NULL THEN
      NEW.created_by := uid;
    END IF;
  ELSE
    NEW.workspace_id := OLD.workspace_id;
    NEW.created_by := OLD.created_by;
    NEW.created_at := OLD.created_at;
  END IF;

  -- Linked rows must live in the same workspace.
  IF NEW.assignee_user_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.assignee_user_id IS DISTINCT FROM OLD.assignee_user_id)
     AND NOT EXISTS (SELECT 1 FROM public.workspace_members m
                     WHERE m.workspace_id = NEW.workspace_id AND m.user_id = NEW.assignee_user_id AND m.status = 'active') THEN
    RAISE EXCEPTION 'assignee_not_member' USING ERRCODE = '23514';
  END IF;
  IF NEW.contact_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.id = NEW.contact_id AND c.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'contact_other_workspace' USING ERRCODE = '23514';
  END IF;
  IF NEW.conversation_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.conversations c WHERE c.id = NEW.conversation_id AND c.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'conversation_other_workspace' USING ERRCODE = '23514';
  END IF;
  IF NEW.deal_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.deals d WHERE d.id = NEW.deal_id AND d.workspace_id = NEW.workspace_id) THEN
    RAISE EXCEPTION 'deal_other_workspace' USING ERRCODE = '23514';
  END IF;

  -- Completion: who/when come from the session, never from the client.
  IF NEW.status = 'done' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'done') THEN
    NEW.completed_at := NOW();
    NEW.completed_by := COALESCE(uid, NEW.completed_by);
  ELSIF NEW.status <> 'done' THEN
    NEW.completed_at := NULL;
    NEW.completed_by := NULL;
  ELSIF uid IS NOT NULL THEN
    NEW.completed_at := OLD.completed_at;
    NEW.completed_by := OLD.completed_by;
  END IF;

  -- A new due date (or reopening) re-arms the reminder.
  IF TG_OP = 'UPDATE' AND (NEW.due_at IS DISTINCT FROM OLD.due_at OR (NEW.status = 'open' AND OLD.status <> 'open')) THEN
    NEW.reminded_at := NULL;
  END IF;
  RETURN NEW;
END;
$$;


