    updated_at timestamp with time zone DEFAULT now(),
    reminder_24h_sent boolean DEFAULT false,
    reminder_3h_sent boolean DEFAULT false,
    feedback_sent boolean DEFAULT false,
    followup_sent boolean DEFAULT false,
    customer_name text,
    sheets_synced boolean DEFAULT false,
    reminder_4h_sent boolean DEFAULT false,
    reminder_2h_sent boolean DEFAULT false,
    workspace_id uuid DEFAULT public.active_ws() NOT NULL,
    service_id uuid,
    product_id uuid,
    duration_minutes integer DEFAULT 30 NOT NULL,
    party_size integer,
    notes text,
    custom_fields jsonb DEFAULT '{}'::jsonb NOT NULL,
    conversation_id uuid,
    ai_agent_id uuid,
    source text DEFAULT 'manual'::text NOT NULL,
    google_event_id text,
    google_calendar_connection_id uuid,
    google_sync_state text,
    google_sync_error text,
    google_sync_attempts integer DEFAULT 0 NOT NULL,
    google_sync_version integer DEFAULT 0 NOT NULL,
    google_synced_at timestamp with time zone,
    viewing_stage_synced_at timestamp with time zone,
    viewing_location_sent_at timestamp with time zone,
    viewing_feedback_sent_at timestamp with time zone,
    viewing_feedback text,
    CONSTRAINT bookings_google_sync_state_check CHECK ((google_sync_state = ANY (ARRAY['pending'::text, 'synced'::text, 'error'::text]))),
    CONSTRAINT bookings_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'completed'::text, 'cancelled'::text, 'no_show'::text]))),
    CONSTRAINT bookings_viewing_feedback_check CHECK (((viewing_feedback IS NULL) OR (viewing_feedback = ANY (ARRAY['interested'::text, 'others'::text, 'not_convinced'::text]))))
);


