--
-- Name: webhook_claim_deliveries(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_claim_deliveries(p_limit integer DEFAULT 50, p_lease_seconds integer DEFAULT 120) RETURNS SETOF public.webhook_deliveries
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH due AS (
    SELECT id FROM public.webhook_deliveries
    WHERE status = 'pending' AND next_attempt_at <= NOW()
    ORDER BY next_attempt_at
    LIMIT GREATEST(1, LEAST(p_limit, 500))
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.webhook_deliveries d
     SET next_attempt_at = NOW() + make_interval(secs => GREATEST(30, p_lease_seconds))
    FROM due
   WHERE d.id = due.id
  RETURNING d.*
$$;


