    'tags', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'color', t.color) ORDER BY t.name)
                        FROM public.contact_tags ct JOIN public.tags t ON t.id = ct.tag_id
                       WHERE ct.contact_id = c.id), '[]'::jsonb),
